public struct LilyTokens: Sendable, Equatable {
    /// The theme's slug in themes/, so an app can match the web theme it pairs with.
    public let slug: String
    public let base100: Color
    public let base200: Color
    public let base300: Color
    public let baseContent: Color
    public let primary: Color
    public let primaryContent: Color
